import{c as a,Q as t,j as n,m as o}from"./chunks/framework.W-g_WCNV.js";const m=JSON.parse('{"title":"Install as an app (PWA)","description":"Add GateKeeper to your home screen as a standalone app on mobile and desktop.","frontmatter":{"title":"Install as an app (PWA)","description":"Add GateKeeper to your home screen as a standalone app on mobile and desktop."},"headers":[],"relativePath":"getting-started/pwa.md","filePath":"getting-started/pwa.md"}'),i={name:"getting-started/pwa.md"};function r(s,e,l,p,d,h){return t(),n("div",null,[...e[0]||(e[0]=[o('<p>GateKeeper ships as a Progressive Web App (PWA). You can install it on your phone or computer and use it like a native app - no browser chrome, standalone window, and a home screen icon.</p><p>There are two separate apps you can install: one for the regular user portal and one for the admin panel.</p><h2 id="installing-on-android-chrome" tabindex="-1">Installing on Android (Chrome) <a class="header-anchor" href="#installing-on-android-chrome" aria-label="Permalink to &quot;Installing on Android (Chrome)&quot;">​</a></h2><p><strong>User app:</strong></p><ol><li>Open GateKeeper in Chrome and sign in.</li><li>Tap the three-dot menu in the top right.</li><li>Tap <strong>Add to Home screen</strong> or <strong>Install app</strong>.</li><li>Confirm - the app installs as <strong>GateKeeper</strong>.</li></ol><p><strong>Admin app:</strong></p><ol><li>Open your admin panel (its own domain, e.g. <code>admin.auth.example.com</code>) and sign in as admin.</li><li>Tap the three-dot menu.</li><li>Tap <strong>Add to Home screen</strong> or <strong>Install app</strong>.</li><li>Confirm - the app installs as <strong>GK Admin</strong> with a distinct icon.</li></ol><p>Both apps can be installed at the same time. They open directly to the correct starting page without browser navigation.</p><h2 id="installing-on-ios-safari" tabindex="-1">Installing on iOS (Safari) <a class="header-anchor" href="#installing-on-ios-safari" aria-label="Permalink to &quot;Installing on iOS (Safari)&quot;">​</a></h2><ol><li>Open GateKeeper (or your admin panel) in Safari.</li><li>Tap the Share button (the box with an arrow pointing up).</li><li>Scroll down and tap <strong>Add to Home Screen</strong>.</li><li>Edit the name if you like, then tap <strong>Add</strong>.</li></ol><p>Repeat the process on the admin panel to add the admin shortcut separately.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Safari on iOS does not show an automatic install prompt like Chrome does. You need to use the Share menu manually.</p></div><h2 id="installing-on-desktop-chrome-edge" tabindex="-1">Installing on desktop (Chrome / Edge) <a class="header-anchor" href="#installing-on-desktop-chrome-edge" aria-label="Permalink to &quot;Installing on desktop (Chrome / Edge)&quot;">​</a></h2><p>Look for the install icon in the browser&#39;s address bar (a small monitor icon or a &quot;+&quot; symbol). Click it and confirm. The app opens in its own window without browser tabs or the address bar.</p><p>On desktop, both the user and admin PWAs can be installed as separate windows.</p><h2 id="updating" tabindex="-1">Updating <a class="header-anchor" href="#updating" aria-label="Permalink to &quot;Updating&quot;">​</a></h2><p>PWAs update automatically. GateKeeper&#39;s service worker checks for a new version on every page load and applies updates in the background. The next time you open the app, it will be running the latest version.</p><h2 id="offline-behavior" tabindex="-1">Offline behavior <a class="header-anchor" href="#offline-behavior" aria-label="Permalink to &quot;Offline behavior&quot;">​</a></h2><p>GateKeeper does not work offline - authentication always requires a server connection. The service worker caches static assets (CSS, fonts, icons) to make the app load faster on slow connections, but the login flow itself always contacts the server.</p>',19)])])}const g=a(i,[["render",r]]);export{m as __pageData,g as default};
